return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'sq','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:51:09+00:00','po-revision-date'=>'2026-11-05T19:51:09+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Plotëson përkthimet që mungojnë për shtesat dhe temat e instaluara tashmë në sajtin tuaj.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Ai ekran ngarkimi ishte i vjetruar: që atëherë është përgatitur një ngarkim tjetër. Nuk u dërgua asgjë. Rishikoni atë aktualin nga Lista e përkthimeve.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Plani i shërbimit falas i jep çdo sajti një numër të kufizuar vendesh për shtesa dhe tema; vendet në përdorim shfaqen te Rregullime pasi të aktivizoni Babilim.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Kërkimi i një përkthimi e vendos këtë shtesë ose temë në një nga vendet e planit të shërbimit falas për këtë sajt (kufiri është %1$d për tema dhe %2$d për shtesa), përveç nëse ka tashmë një. Një vend mbetet i përdorur dhe një përkthim i dështuar nuk e liron.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Kërkimi i një përkthimi e vendos këtë shtesë ose temë në një nga vendet e planit të shërbimit falas për këtë sajt, përveç nëse ka tashmë një. Një vend mbetet i përdorur dhe një përkthim i dështuar nuk e liron.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Nëse kjo shtesë ose temë nuk është ende në një nga vendet e planit të shërbimit falas për këtë sajt, kërkimi i një përkthimi e vendos në një të tillë (kufiri është %1$d për tema dhe %2$d për shtesa). Një vend mbetet i përdorur dhe një përkthim i dështuar nuk e liron. Të vazhdohet?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Nëse kjo shtesë ose temë nuk është ende në një nga vendet e planit të shërbimit falas për këtë sajt, kërkimi i një përkthimi e vendos në një të tillë. Një vend mbetet i përdorur dhe një përkthim i dështuar nuk e liron. Të vazhdohet?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d sajt në këtë rrjet është caktuar të fshijë identitetin e tij Babilim kur shtojca të fshihet. Licenca me pagesë e lidhur me atë sajt më pas nuk mund të rikthehet automatikisht; do të duhet të kontaktoni mbështetjen e Babilim te %2$s. Për ta ruajtur identitetin, shtypni Anulo, hiqni shenjën te "Delete all Babilim data on uninstall" te rregullimet e Babilim të atij sajti dhe çaktivizojeni përsëri. Ta çaktivizoj gjithsesi?' . "\0" . '%1$d sajte në këtë rrjet janë caktuar të fshijnë identitetin e tyre Babilim kur shtojca të fshihet. Licenca me pagesë e lidhur me ato sajte më pas nuk mund të rikthehet automatikisht; do të duhet të kontaktoni mbështetjen e Babilim te %2$s. Për t\'i ruajtur identitetet, shtypni Anulo, hiqni shenjën te "Delete all Babilim data on uninstall" te rregullimet e Babilim të secilit sajt dhe çaktivizojeni përsëri. Ta çaktivizoj gjithsesi?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s asgjë për të bërë.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Zgjidhni gjuhën.','%d failed'=>'%d dështoi' . "\0" . '%d dështuan','%d not yet tried'=>'%d ende pa u provuar' . "\0" . '%d ende pa u provuar','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d raport është në pritje. "Always share" dhe "Don\'t share" vlejnë për të gjitha.' . "\0" . '%d raporte janë në pritje. "Always share" dhe "Don\'t share" vlejnë për të gjitha.','%d skipped'=>'%d u anashkalua' . "\0" . '%d u anashkaluan','%d succeeded'=>'%d me sukses' . "\0" . '%d me sukses','%d to install'=>'%d për t\'u instaluar' . "\0" . '%d për t\'u instaluar','(a public key generated for this site)'=>'(një çelës publik i krijuar për këtë sajt)','(detected)'=>'(i zbuluar)','(generic codes and coordinates only)'=>'(vetëm kode të përgjithshme dhe koordinata)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Një pastrim u pezullua më %1$s: %2$s. Nuk u fshi asgjë.','A file in the component could not be read, so it was not packaged.'=>'Një kartelë në komponent nuk mund të lexohej, prandaj nuk u paketua.','A host that serves only one PHP request at a time cannot complete this step.'=>'Një strehues që shërben vetëm një kërkesë PHP në çdo kohë nuk mund ta përfundojë këtë hap.','A part of the upload kept failing, so the upload was cancelled.'=>'Një pjesë e ngarkimit vazhdoi të dështonte, ndaj ngarkimi u anulua.','A translation cannot be requested for that locale on this site right now.'=>'Për këtë vendndodhje gjuhësore nuk mund të kërkohet përkthim në këtë sajt për momentin.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Një shkrim në indeksin e përkthimeve u përplas me një kërkesë tjetër më %1$s (%2$s) dhe nuk u zbatua; u mbajt versioni më i fundit.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Një shkrim në indeksin e përkthimeve më %1$s (%2$s) nuk mund të përfundonte dhe nuk u zbatua (%3$s).','Account'=>'Llogaria','Add another language'=>'Shto një gjuhë tjetër','Advanced'=>'Të mëtejshme','All'=>'Të gjitha','All free-plan slots for this site are used'=>'Të gjitha vendet e planit falas për këtë sajt janë në përdorim','All languages'=>'Të gjitha gjuhët','Already in WordPress core'=>'Tashmë në bërthamën e WordPress','Already installed.'=>'Tashmë i instaluar.','Always share'=>'Always share','Another installation is running; try again in a moment.'=>'Një instalim tjetër po ekzekutohet; provoni përsëri pas pak.','Automatic installs'=>'Instalime automatike','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Instalimet automatike tani janë joaktive; aktivizojini përsëri te rregullimet nëse i doni.','Available'=>'Të disponueshme','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Përkthimet e disponueshme mund të instalohen me një klik, ndërsa ato që mungojnë mund të kërkohen. Kur instalimet automatike janë aktive, përkthimet që shërbimi i liston si të disponueshme për gjuhët që administroni instalohen gjatë sinkronizimit dy herë në ditë.','Available · %s'=>'I disponueshëm · %s','Babilim Settings'=>'Rregullimet e Babilim','Babilim adds translations for every language checked here.'=>'Babilim shton përkthime për çdo gjuhë të zgjedhur këtu.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim nuk mundi të konfirmonte një dosje të përkohshme jashtë sajtit, ndaj komponenti nuk u paketua dhe asgjë nuk u ngarkua. Përcaktoni BABILIM_TEMP_DIR në wp-config.php si një dosje të shkrueshme jashtë web root (për shembull një dosje pranë, jo brenda, dosjes publike të sajtit tuaj), ose kërkojani një ofruesit tuaj të pritjes.','Babilim could not finish checking this site.'=>'Babilim nuk e përfundoi dot kontrollin e këtij sajti.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim nuk e përfundoi dot aktivizimin (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim nuk arriti ta përfundojë verifikimin e këtij sajti (shërbimi nuk e kontaktoi dot). Regjistrimi është pezulluar.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim nuk e verifikoi dot këtë sajt, ndaj asgjë nuk shkarkohet ose instalohet derisa verifikimi të kryhet me sukses.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim nuk e verifikoi dot këtë sajt, ndaj nuk shkarkohet dhe nuk instalohet asgjë.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim gjen shtojcat dhe temat në këtë sajt që nuk kanë përkthim për gjuhën tuaj dhe instalon një për secilën.','Babilim has not been enabled for this site yet.'=>'Babilim nuk është aktivizuar ende për këtë sajt.','Babilim has not installed any translation for this language.'=>'Babilim nuk ka instaluar asnjë përkthim për këtë gjuhë.','Babilim hit an error. Share an error report?'=>'Babilim has hasur në një gabim. Të ndahet një raport gabimi?','Babilim installed %d translation automatically since your last visit.'=>'Babilim instaloi %d përkthim automatikisht që nga vizita juaj e fundit.' . "\0" . 'Babilim instaloi %d përkthime automatikisht që nga vizita juaj e fundit.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim është çaktivizuar. Nuk dërgohet më asgjë; përkthimet e instaluara tashmë vazhdojnë të funksionojnë.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim është aktivizuar: ky sajt është i verifikuar dhe u gjet %d komponent.' . "\0" . 'Babilim është aktivizuar: ky sajt është i verifikuar dhe u gjetën %d komponentë.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim po e aktivizon dhe po e kontrollon këtë sajt… (përpjekja e fundit: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim po e aktivizon dhe po e kontrollon këtë sajt… Rifreskoni këtë faqe ose prisni që kontrolli i planifikuar të përfundojë.','Babilim is not enabled.'=>'Babilim nuk është i aktivizuar.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim është caktuar të fshijë identitetin e këtij sajti kur shtojca të fshihet. Licenca me pagesë e lidhur me këtë sajt më pas nuk mund të rikthehet automatikisht; do të duhet të kontaktoni mbështetjen e Babilim te %s. Për ta ruajtur identitetin, shtypni Anulo, hiqni shenjën te "Delete all Babilim data on uninstall" te rregullimet e Babilim dhe çaktivizojeni përsëri. Ta çaktivizoj gjithsesi?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim e kaloi kohën për këtë hap dhe do të vazhdojë në kontrollin e radhës.','Babilim settings'=>'Rregullimet e Babilim','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Sinkronizimi i Babilim është vonuar përkohësisht nga shërbimi (kufizim shpejtësie); do të provojë përsëri pas %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim u përditësua ndërsa ky ngarkim po priste. Paketa e vjetër u hodh poshtë; ju lutemi konfirmoni ngarkimin përsëri.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim do të ngarkojë këto kartela nga %1$s (versioni %2$s): çdo kartelë .php dhe .js, çdo kartelë block.json, si dhe readme.txt, readme.md, style.css dhe theme.json në dosjen e tij kryesore. Ato përdoren për të gjetur tekstin që duhet përkthyer dhe për të identifikuar shtesën ose temën.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest nuk është i disponueshëm: %s','Back'=>'Mbrapa','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Keni blerë më parë një licencë për këtë domen? Futni kodin e rikthimit që morët gjatë blerjes.','Broken placeholder'=>'Vendmbajtës i prishur','Build'=>'Build','Built'=>'Ndërtuar','Bulk actions apply only to the selected language of each selected component.'=>'Veprimet masive zbatohen vetëm për gjuhën e përzgjedhur të çdo komponenti të përzgjedhur.','Bulk actions apply to every matching language of each selected component.'=>'Veprimet masive zbatohen për çdo gjuhë të çdo komponenti të përzgjedhur që përputhet me filtrin.','Bulk download:'=>'Shkarkim në masë:','Bulk request:'=>'Kërkesë në masë:','Bulk update:'=>'Përditësim në masë:','Bundled with the plugin'=>'I përfshirë me shtesën','Bundled with the theme'=>'I përfshirë me temën','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Duke klikuar Aktivizo, pranoni të dërgoni te Babilim informacionin e listuar më sipër.','By continuing you confirm that you have the right to upload this component.'=>'Duke vazhduar, konfirmoni se keni të drejtën të ngarkoni këtë komponent.','Cancel'=>'Anulo','Category'=>'Kategori','Check again'=>'Kontrollo përsëri','Check again now'=>'Kontrollo përsëri tani','Checkout is not available for this site right now.'=>'Përfundimi i Blerjes nuk është i disponueshëm për këtë sajt për momentin.','Choose'=>'Zgjidh','Choose a category…'=>'Zgjidh një kategori…','Choose a language'=>'Zgjidhni një gjuhë','Choose a language…'=>'Zgjidhni një gjuhë…','Clear filters'=>'Pastro filtrat','Close'=>'Mbyll','Component'=>'Komponent','Confirm'=>'Konfirmo','Conflicting keys'=>'Çelësa në konflikt','Continue'=>'Vazhdo','Continue next batch (%d left)'=>'Vazhdo me grupin tjetër (mbeten %d)','Continuing…'=>'Po vazhdohet…','Could not back up %s before replacing it.'=>'Nuk u kopjeruajt dot %s para zëvendësimit.','Could not create the package archive.'=>'Arkivi i paketës nuk mund të krijohej.','Could not determine active components; the existing merged index was left unchanged.'=>'Komponentët aktivë nuk mund të përcaktoheshin; indeksi i bashkuar ekzistues u la i pandryshuar.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Nuk u përcaktuan dot shtojcat/temat e instaluara; pastrimi u anashkalua, nuk u fshi asgjë.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Nuk u ngarkua dot lista e plotë e vendndodhjeve gjuhësore të WordPress.org nga shërbimi, ndaj aktualisht nuk mund të shtohet asnjë gjuhë tjetër.','Could not move %s into place.'=>'Nuk u zhvendos dot %s në vend.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Indeksi i bashkuar për \'%s\' nuk mund të zhvendosej në vend; indeksi i mëparshëm i shërbyer (nëse ka pasur) u hoq në vend që të lihej përgjysmë i përditësuar. Për këtë vendndodhje gjuhësore nuk shërbehet asnjë plotësim i domenit parazgjedhur deri në rindërtimin e ardhshëm të suksesshëm.','Could not open zip: %s'=>'Zip nuk mund të hapej: %s','Could not prepare %s for rollback.'=>'%s nuk mund të përgatitej për rikthim.','Could not read %s back after moving it into place.'=>'%s nuk mund të lexohej përsëri pasi u zhvendos në vend.','Could not read: %s'=>'Nuk u lexua dot: %s','Could not restore the purchase: %s'=>'Blerja nuk u rikthye dot: %s','Could not show a new restore code: %s'=>'Nuk u shfaq dot një kod i ri rikthimi: %s','Could not stage %s'=>'Nuk u përgatit dot %s','Could not stage default/%s'=>'Nuk u arrit të përgatitej default/%s','Could not start checkout: %s'=>'Nuk u nis dot Përfundimi i Blerjes: %s','Could not verify entry count for %s'=>'Nuk u verifikua dot numri i zërave për %s','Could not write the downloaded package to disk.'=>'Paketa e shkarkuar nuk mund të shkruhej në disk.','Could not write the staged merged index.'=>'Indeksi i bashkuar në përgatitje nuk mund të shkruhej.','Current translation'=>'Përkthimi aktual','Custom overrides'=>'Mbishkrime të personalizuara','Danger zone'=>'Zona e rrezikshme','Default supplement entry count mismatch.'=>'Numri i zërave të suplementit Parazgjedhje nuk përputhet.','Delete all Babilim data on uninstall'=>'Fshije të gjitha të dhënat e Babilim gjatë çinstalimit','Disable Babilim'=>'Çaktivizo Babilim','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Të çaktivizohet Babilim? Përkthimet e instaluara ruhen, por nuk do të kryhen më kontrolle ose shkarkime.','Don\'t share'=>'Don\'t share','Download'=>'Shkarko','Downloaded and installed.'=>'U shkarkua dhe u instalua.','Downloading…'=>'Po shkarkohet…','Downloads: %1$d/%2$d (%3$s)'=>'Shkarkime: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Kontributi i secilit komponent te plotësimi i përbashkët i domenit parazgjedhur të çdo vendndodhjeje gjuhësore.','Enable Babilim'=>'Aktivizo Babilim','Enabling…'=>'Po aktivizohet…','English (United States)'=>'English (United States)','Entries'=>'Hyrje','Entry count mismatch for %s'=>'Mospërputhje e numrit të zërave për %s','Error reports'=>'Raportet e gabimeve','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Çdo shtojcë/temë e instaluar: slug-u, versioni, domeni(et) e tekstit, nëse është në WordPress.org, vendndodhjet e veta gjuhësore të përfshira dhe për cilat vendndodhje gjuhësore keni instaluar tashmë një përkthim Babilim.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Çdo vendndodhje gjuhësore në përdorim në këtë sajt (vendndodhja e sajtit, paketat gjuhësore të instaluara, vendndodhjet e përdoruesve dhe çdo vendndodhje që shtoni dorazi). Asnjë vendndodhje nuk trajtohet ndryshe nga tjetra.','Excluded'=>'Përjashtuar','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Kartelat me emra ose shtesa të tjera nuk përfshihen, as dosjet uploads, cache, logs, backup, data, vendor, node_modules dhe languages, kartelat e fshehura, ose kartelat emrat e të cilave përputhen me sekrete të zakonshme (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Kartelat e kodit mund të përmbajnë prapë tekst ose të dhëna që nuk do të donit t\'i ndanit; kontrolloni ato nëse nuk jeni të sigurt. Shërbimi i heq përsëri të njëjtat lloje kartelash kur mbërrijnë.','Free'=>'Falas','Free-plan slots'=>'Vende të planit falas','General'=>'Të përgjithshme','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Nëse kjo është e aktivizuar, çinstalimi fshin gjithashtu identitetin e këtij sajti. Licenca me pagesë e lidhur me këtë sajt nuk mund të rikthehet automatikisht më pas; do të duhet të kontaktoni mbështetjen e Babilim te %s për ta rimarrë.','Included'=>'Përfshirë','Included in index'=>'Përfshirë në indeks','Install available translations automatically'=>'Instalo automatikisht përkthimet e disponueshme','Installed'=>'Të instaluara','Installed translations are kept, but no further checks or downloads will run.'=>'Përkthimet e instaluara ruhen, por nuk do të kryhen më kontrolle ose shkarkime.','Installed · %s'=>'Instaluar · %s','Installed · built for %1$s, this site has %2$s'=>'I instaluar · ndërtuar për %1$s, ky sajt ka %2$s','Installed · built for %s'=>'I instaluar · ndërtuar për %s','Installed · built for %s, all free-plan slots for this site are used'=>'Instaluar · ndërtuar për %s, të gjitha vendet e planit falas për këtë sajt janë në përdorim','Installed · built for %s, new version failed'=>'Instaluar · ndërtuar për %s, versioni i ri dështoi','Installed · built for %s, new version not covered by the free service plan'=>'Instaluar · ndërtuar për %s, versioni i ri nuk mbulohet nga plani falas i shërbimit','Installed · built for %s, new version scheduled'=>'I instaluar · ndërtuar për %s, versioni i ri është planifikuar','Installed · built for %s, translating the new version…'=>'I instaluar · ndërtuar për %s, po përkthehet versioni i ri…','Installed · built for a different version'=>'I instaluar · ndërtuar për një version tjetër','Installed · built for a different version, all free-plan slots for this site are used'=>'Instaluar · ndërtuar për një version tjetër, të gjitha vendet e planit falas për këtë sajt janë në përdorim','Installed · built for a different version, new version failed'=>'Instaluar · ndërtuar për një version tjetër, versioni i ri dështoi','Installed · built for a different version, new version not covered by the free service plan'=>'Instaluar · ndërtuar për një version tjetër, versioni i ri nuk mbulohet nga plani falas i shërbimit','Installed · built for a different version, new version scheduled'=>'I instaluar · ndërtuar për një version tjetër, versioni i ri është planifikuar','Installed · built for a different version, translating the new version…'=>'I instaluar · ndërtuar për një version tjetër, po përkthehet versioni i ri…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Ruhet nga ofruesi i hostimit të shërbimit dhe përpunohet nga modele të AI-së për të prodhuar përkthimin.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Ruaj mbivendosjet e mia të përkthimit kur pastrohet gjithçka ose kur çinstalohet ky shtesë.','Language'=>'Gjuhë','Language:'=>'Gjuhë:','Languages'=>'Gjuhët','Languages found on this site: %s.'=>'Gjuhët e gjetura në këtë sajt: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Pastrimi i fundit më %1$s: %2$d të shënuara rishtazi, %3$d kartela të fshira, %4$d regjistrime të hequra.','Maintenance'=>'Mirëmbajtje','Maintenance status is not available right now.'=>'Gjendje e mirëmbajtjes nuk është e disponueshme tani.','Manifest unavailable: %s'=>'Manifesti nuk është i disponueshëm: %s','Negation reversed'=>'Mohim i përmbysur','No'=>'Jo','No build is available to download for this locale.'=>'Nuk ka asnjë build të gatshëm për shkarkim për këtë vendndodhje gjuhësore.','No cleanup has run yet.'=>'Ende nuk është ekzekutuar asnjë pastrim.','No components match these filters. %s'=>'Asnjë komponent nuk përputhet me këta filtra. %s','No components synced yet.'=>'Ende nuk është sinkronizuar asnjë komponent.','No installed translation matches.'=>'Asnjë përkthim i instaluar nuk përputhet.','No language is managed yet.'=>'Ende nuk administrohet asnjë gjuhë.','No pending challenge for this nonce.'=>'Nuk ka sfidë në pritje për këtë nonce.','No pending challenge to verify.'=>'Nuk ka asnjë sfidë në pritje për t\'u verifikuar.','No plugins or themes found.'=>'Nuk u gjetën shtojca ose tema.','No previous build to roll back to.'=>'Nuk ka ndërtim të mëparshëm për rikthim.','No record for %s'=>'Nuk ka regjistrim për %s','No site id is on file to rotate a token for.'=>'Nuk ka ID sajti të ruajtur për të rrotulluar një token.','No — component inactive'=>'Jo — komponenti është joaktiv','No — component removed'=>'Jo — komponenti është hequr','No — installed version differs from the active one'=>'Jo — versioni i instaluar ndryshon nga ai aktiv','Not a valid server_build_id: %s'=>'Nuk është server_build_id i vlefshëm: %s','Not covered by the free service plan'=>'Nuk mbulohet nga plani falas i shërbimit','Not installed'=>'Nuk është instaluar','Not registered yet'=>'Ende i paregjistruar','Not supported'=>'Nuk mbështetet','Not verified'=>'E paverifikuar','Note (optional)'=>'Shënim (opsional)','Nothing to choose.'=>'Nuk ka asgjë për të zgjedhur.','Nothing to confirm.'=>'Nuk ka asgjë për të konfirmuar.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'I çaktivizuar si parazgjedhje: fshirja e shtesës e ruan identitetin e këtij sajti, kështu që një riinstalim mund ta ripërdorë.','One or more served files no longer match the manifest.'=>'Një ose më shumë kartela të shërbyera nuk përputhen më me manifestin.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Blerje e njëhershme për këtë sajt: %1$s %2$s. Përfshin të gjitha përditësimet e ardhshme të përkthimeve. Pagesa trajtohet nga Paddle në një skedë të re.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Këtë mund ta bëjë vetëm një administrator i rrjetit, sepse ndryshon skedarët e përkthimit që ndahen nga çdo sajt në këtë rrjet.','Only plugins and themes can be packaged.'=>'Mund të paketohen vetëm shtojcat dhe temat.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Vetëm kur konfirmoni një ngarkim për një shtesë ose temë që nuk është në WordPress.org: çdo kartelë .php dhe .js, çdo kartelë block.json, si dhe readme.txt, readme.md, style.css dhe theme.json në dosjen kryesore të atij komponenti, si zip, pasi kartelat që përputhen me sekrete të zakonshme janë lënë jashtë.','Open Babilim settings'=>'Hap rregullimet e Babilim','Original language'=>'Gjuha origjinale','Original string'=>'Vargu origjinal','Paid'=>'Me pagesë','Partner'=>'Partner','Please check that your site can be reached from the internet, then try again.'=>'Ju lutemi kontrolloni që sajti juaj të jetë i arritshëm nga interneti, pastaj provoni përsëri.','Please choose a category for this report.'=>'Ju lutemi zgjidhni një kategori për këtë raport.','Plugin'=>'Shtesë','Plugin · %s'=>'Shtojcë · %s','Plugins'=>'Shtojca','Preview'=>'Pamja paraprake','Purchase restored. This site is now licensed.'=>'Blerja u rikthye. Ky sajt tani ka licencë.','Re-parsed entry count did not match the built index.'=>'Numri i hyrjeve të rianalizuara nuk përputhej me indeksin e ndërtuar.','Re-verify'=>'Verifiko përsëri','Rebuild index now'=>'Rindërto indeksin tani','Refusing to write outside the Babilim language-file directory.'=>'Refuzohet shkrimi jashtë drejtorisë së kartelave gjuhësore të Babilim.','Registration response was missing required fields.'=>'Përgjigjes së regjistrimit i mungonin fushat e nevojshme.','Registration restarted.'=>'Regjistrimi u rinis.','Remove'=>'Hiq','Remove everything Babilim installed'=>'Hiq gjithçka që instaloi Babilim','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Të hiqet gjithçka që instaloi Babilim? Kjo fshin çdo kartelë gjuhe që Babilim ka instaluar për çdo shtesë dhe temë në këtë sajt.','Remove the %2$s translation of %1$s from this site?'=>'Të hiqet përkthimi %2$s i %1$s nga ky sajt?','Removed %d installed component.'=>'U hoq %d komponent i instaluar.' . "\0" . 'U hoqën %d komponentë të instaluar.','Removed after a failed integrity check'=>'U hoq pas një kontrolli të dështuar integriteti','Removed.'=>'U hoq.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Heq çdo kartelë gjuhe që Babilim ka instaluar për çdo shtesë dhe temë në këtë sajt.','Report a problem'=>'Raporto një problem','Report translation'=>'Raporto përkthimin','Request newer translation'=>'Kërko përkthim më të ri','Request translation'=>'Kërko përkthim','Requestable'=>'I kërkueshëm','Requesting…'=>'Po kërkohet…','Restart registration'=>'Rinis regjistrimin','Restore code'=>'Kodi i rikthimit','Restore purchase'=>'Rikthe blerjen','Retry request'=>'Provo përsëri kërkesën','Roll back'=>'Rikthe','Roll back and report'=>'Rikthe dhe raporto','Roll back and send report'=>'Riktheje dhe dërgo raportin','Roll back the %2$s translation of %1$s to the previous build?'=>'Ta rikthej përkthimin %2$s të %1$s te ndërtimi i mëparshëm?','Rolled back and reported.'=>'U kthye pas dhe u raportua.','Rolled back to the previous build.'=>'U kthye te build-i i mëparshëm.','Rolled back, but the report could not be sent: %s'=>'U kthye pas, por raporti nuk mund të dërgohej: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Rikthimi do të mbishkruante \'%1$s\' (%2$s), që tani shërbehet për një komponent tjetër të instaluar (%3$s); asgjë nuk u ndryshua.','Rotate-token response was missing site_token.'=>'Përgjigjes së rrotullimit të tokenit i mungonte site_token.','Save changes'=>'Ruaj ndryshimet','Scheduled, waiting to be processed'=>'Planifikuar, në pritje të përpunimit','Search'=>'Kërko','Search components'=>'Kërko komponentë','Search the installed translations'=>'Kërko te përkthimet e instaluara','Select all'=>'Zgjidh të gjitha','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Përzgjidhni më pak komponentë: më së shumti %1$d veprime për çdo ekzekutim (keni përzgjedhur %2$d).','Send report'=>'Dërgo raportin','Service plan'=>'Plani i shërbimit','Settings'=>'Rregullime','Share error reports'=>'Ndaj raportet e gabimeve','Share this report'=>'Ndaje këtë raport','Show a new restore code'=>'Shfaq një kod të ri rikthimi','Show the "Report translation" entry in the admin toolbar'=>'Shfaq opsionin "Raporto përkthimin" në shiritin e veglave të administrimit','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Një pjesë e tekstit të këtij komponenti është shkruar drejtpërdrejt në kod nga autori i tij dhe nuk mund të përkthehet me një paketë gjuhësore.','Status'=>'Gjendje','Status unknown'=>'Gjendje e panjohur','String context'=>'Konteksti i vargut','Suggested translation'=>'Përkthim i sugjeruar','Supplementary translation index'=>'Indeksi i përkthimeve plotësuese','Supplementary translation index rebuilt.'=>'Indeksi plotësues i përkthimeve u rindërtua.','Supplementary translation maintenance'=>'Mirëmbajtja e përkthimeve shtesë','Supplementary translations'=>'Përkthime plotësuese','Sweep aborted without orphaning anything: %s.'=>'Pastrimi u ndërpre pa lënë asgjë jetim: %s.','Sweep complete: %d file deleted.'=>'Pastrimi përfundoi: u fshi %d kartelë.' . "\0" . 'Pastrimi përfundoi: u fshinë %d kartela.','Sweep now'=>'Pastro tani','Sync complete.'=>'Sinkronizimi përfundoi.','Thank you. Your report was sent.'=>'Faleminderit. Raporti juaj u dërgua.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Ky komponent nuk është i instaluar në këtë sajt, ndaj nuk mund të kërkohet përkthim për të.','That does not look like a restore code.'=>'Ky nuk duket si kod rikthimi.','That is not a valid WordPress locale code. Nothing was saved.'=>'Ky nuk është kod i vlefshëm vendndodhjeje gjuhësore të WordPress. Nuk u ruajt asgjë.','That is not a valid build identifier.'=>'Ky nuk është një identifikues i vlefshëm i ndërtimit.','The change could not be recorded in the translation index; please try again.'=>'Ndryshimi nuk mund të regjistrohej në indeksin e përkthimeve; ju lutemi provoni përsëri.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Pastrimi u ekzekutua, por disa nga ndryshimet e tij nuk mund të regjistroheshin në indeksin e përkthimeve; pastrimi i radhës do t\'i provojë përsëri.','The component has no files that can be uploaded.'=>'Komponenti nuk ka kartela që mund të ngarkohen.','The component is not inside the plugins or themes directory.'=>'Komponenti nuk ndodhet brenda direktorisë së shtojcave ose të temave.','The component\'s main file was not found.'=>'Kartela kryesore e komponentit nuk u gjet.','The download response was missing a usable location.'=>'Përgjigjes së shkarkimit i mungonte një vendndodhje e përdorshme.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Opsioni hap një panel për të kërkuar përkthimet që Babilim instaloi në këtë sajt dhe për të raportuar një prej tyre.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Fusha "%1$s" është shumë e gjatë: ka %2$d karaktere dhe kufiri është %3$d. Nuk u dërgua asgjë; ju lutemi shkurtojeni dhe provoni përsëri.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Domeni i dhënë \'%1$s\' nuk përputhet as me slug-un e vet të manifestit të paketës \'%2$s\', as me text_domain të tij \'%3$s\'.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Indeksi i bashkuar për \'%s\' u rindërtua, por indeksi i përkthimeve nuk mundi ta regjistronte; rindërtimi i radhës do ta provojë përsëri.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Teksti origjinal dhe përkthimet e bëra prej tij do t\'u jepen sajteve të tjera që instalojnë të njëjtin version.','The package declares no main translation file.'=>'Paketa nuk deklaron kartelë kryesore përkthimi.','The package has no %s for its own text domain.'=>'Paketa nuk ka %s për domenin e vet të tekstit.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Lloji \'%1$s\' i manifestit të paketës nuk përputhet me llojin e kërkuar \'%2$s\'.','The package produced no servable main translation file.'=>'Paketa nuk prodhoi kartelë kryesore përkthimi që mund të shërbehet.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Domeni i tekstit \'%1$s\' i paketës nuk përputhet me kopjen e komponentit në këtë sajt (\'%2$s\'), prandaj nuk u instalua.','The packaged component could not be read.'=>'Komponenti i paketuar nuk mund të lexohej.','The registration challenge is not in the expected form.'=>'Sfida e regjistrimit nuk është në formën e pritur.','The report could not be sent.'=>'Raporti nuk u dërgua dot.','The search could not be completed.'=>'Kërkimi nuk u plotësua dot.','The service asked this site to wait before syncing again.'=>'Shërbimi i kërkoi këtij sajti të presë përpara se të sinkronizojë përsëri.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Shërbimi nuk e arriti dot sajtin tuaj. Ka gjasa që një firewall, një shtojcë sigurie ose një rregull i strehuesit po e bllokon kërkesën; ju lutemi lejoni kërkesat te /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Oferta e shërbimit për ngarkim ishte e paplotë.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Domeni i tekstit \'%1$s\' (%2$s) shërbehet tashmë për një komponent tjetër të instaluar (%3$s); asgjë nuk u instalua.','The upload is kept until you ask Babilim to delete it.'=>'Ngarkimi ruhet derisa t\'i kërkoni Babilim ta fshijë.','Theme'=>'Temë','Theme · %s'=>'Temë · %s','Themes'=>'Tema','There is no upload in progress.'=>'Nuk ka asnjë ngarkim në vazhdim.','There is no upload waiting for confirmation.'=>'Nuk ka asnjë ngarkim në pritje të konfirmimit.','These are the languages this site uses. You can change them in %s.'=>'Këto janë gjuhët që përdor ky sajt. Mund t\'i ndryshoni te %s.','These fields will be sent:'=>'Këto fusha do të dërgohen:','This build is not one this site currently knows about for this component/locale.'=>'Ky build nuk është një nga ato që ky sajt i njeh aktualisht për këtë komponent/vendndodhje gjuhësore.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Ky komponent nuk deklaron numër versioni, ndaj nuk mund të kërkohet përkthim për të.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Ky komponent është më i madh se sa pranon shërbimi, ndaj nuk mund të ngarkohet.','This component was already uploaded. Babilim is checking it now.'=>'Ky komponent u ngarkua tashmë. Babilim po e kontrollon tani.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Numri i versionit të këtij komponenti është më i gjatë se %d shenja, çka Babilim nuk mund ta trajtojë, ndaj nuk mund të kërkohet përkthim për të.','This issues a new restore code and the previous one stops working. Continue?'=>'Kjo lëshon një kod të ri rikthimi dhe i mëparshmi pushon së funksionuari. Të vazhdohet?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Ky rrjet ka shumë sajte për t\'i kontrolluar një nga një dhe disa prej tyre mund të jenë caktuar të fshijnë identitetin e tyre Babilim kur shtojca të fshihet. Licenca me pagesë e lidhur me një sajt të tillë më pas nuk mund të rikthehet automatikisht; do të duhet të kontaktoni mbështetjen e Babilim te %s. Për t\'i ruajtur identitetet, shtypni Anulo, hiqni shenjën te "Delete all Babilim data on uninstall" te rregullimet e Babilim të secilit sajt dhe çaktivizojeni përsëri. Ta çaktivizoj gjithsesi?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Versioni i vetë kësaj shtojce, që shërbimi t\'ju kërkojë ta përditësoni nëse është shumë i vjetër për të komunikuar me të.','This report does not name a valid plugin or theme and locale.'=>'Ky raport nuk emërton një shtojcë ose temë dhe vendndodhje gjuhësore të vlefshme.','This report does not name an installed string.'=>'Ky raport nuk përmend asnjë varg teksti të instaluar.','This report is missing a valid build to report against.'=>'Këtij raporti i mungon një build i vlefshëm për t\'u raportuar.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Ky raport do të postohet publikisht në GitHub dhe mund të ruhet nga palë të treta.','This restore code was not recognised for this site.'=>'Ky kod rikthimi nuk u njoh për këtë sajt.','This site already has an active registration that can no longer be recovered automatically.'=>'Ky sajt ka tashmë një regjistrim aktiv që nuk mund të rikuperohet më automatikisht.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Ky sajt ka %1$d komponentë në %2$d gjuhë, çka kërkon %3$d grupe kontrolli; Babilim mund të trajtojë më së shumti %4$d për çdo ekzekutim. Zvogëloni gjuhët e menaxhuara te Rregullime ose çaktivizoni shtesat dhe temat e papërdorura, pastaj shtypni Kontrollo përsëri tani.','This site has no purchase to show a code for.'=>'Ky sajt nuk ka blerje për të cilën të shfaqet kod.','This site is already licensed. Reload the page.'=>'Ky sajt është licencuar tashmë. Ringarkoni faqen.','This site is not registered with Babilim yet.'=>'Ky sajt nuk është regjistruar ende në Babilim.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Ky sajt e kalon madhësinë që shërbimi pranon në një sinkronizim, ndaj disa elemente u lanë jashtë: %1$d komponentë dhe %2$d gjuhë.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Ky sajt është pjesë e një rrjeti multisite, i cili nuk instalon automatikisht përkthime të reja. Përkthimet që janë instaluar tashmë përditësohen prapë.','This site is verified.'=>'Ky sajt është i verifikuar.','This site must be verified first.'=>'Ky sajt duhet të verifikohet fillimisht.','This site\'s URL, so the service can verify you own it.'=>'URL-ja e këtij sajti, që shërbimi të verifikojë se ju e zotëroni.','This site\'s address is too long for Babilim to register.'=>'Adresa e këtij sajti është shumë e gjatë për t\'u regjistruar nga Babilim.','This site\'s configured locale.'=>'Vendndodhja gjuhësore e konfiguruar e këtij sajti.','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Çelësi publik i instalimit të këtij sajti, përdorur për të provuar se kërkesat vijnë vërtet nga ky sajt. Dërgohet vetëm pjesa publike.','This site\'s locale code is not one Babilim can register.'=>'Kodi i vendndodhjes gjuhësore të këtij sajti nuk është i tillë që Babilim ta regjistrojë.','This string can\'t be reported from this site.'=>'Ky varg nuk mund të raportohet nga ky sajt.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Ky varg teksti nuk është mes përkthimeve të instaluara në këtë sajt. Kërkoni përsëri dhe zgjidheni nga lista.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Ky përkthim u përditësua pasi kërkuat. Kërkoni përsëri dhe zgjidheni vargun nga lista e re.','To translate this component, Babilim needs its source.'=>'Për ta përkthyer këtë komponent, Babilim ka nevojë për burimin e tij.','Too many attempts. Try again tomorrow.'=>'Shumë përpjekje. Provoni përsëri nesër.','Too many reports today. Try again tomorrow.'=>'Shumë raporte sot. Provo përsëri nesër.','Too many requests.'=>'Shumë kërkesa.','Toolbar'=>'Shiriti i veglave','Translating…'=>'Po përkthehet…','Translation does not load'=>'Përkthimi nuk ngarkohet','Translation failed'=>'Përkthimi dështoi','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Skedarët e përkthimit që vendosni në %s kanë gjithmonë përparësi ndaj atyre të Babilim. Ruhen, përveç nëse e çzgjidhni këtë.','Translation requested.'=>'Përkthimi u kërkua.','Translations'=>'Përkthime','Type'=>'Lloj','Type at least 2 characters to search.'=>'Shkruani të paktën 2 karaktere për të kërkuar.','Unexpected HTTP %d response.'=>'Përgjigje e papritur HTTP %d.','Uninstall'=>'Çinstalo','Unknown kind: %s'=>'Lloj i panjohur: %s','Unsafe domain: %s'=>'Domain i pasigurt: %s','Unsafe locale: %s'=>'Vendndodhje gjuhësore e pasigurt: %s','Unsafe slug: %s'=>'Slug i pasigurt: %s','Unsafe text_domain: %s'=>'text_domain i pasigurt: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Deri në 20 ngjarje diagnostikimi në pritje (p.sh. një kartelë që dështoi në kontrollin e integritetit), secila vetëm me një kod, komponent dhe vendndodhje gjuhësore, dhe kurrë me përmbajtje vargjesh apo tekst të përkthyer.','Update'=>'Përditëso','Update available'=>'Përditësim i disponueshëm','Updates'=>'Përditësime','Updating…'=>'Po përditësohet…','Upgrade this site'=>'Përmirëso këtë sajt','Upload and request'=>'Ngarko dhe kërko','Upload cancelled.'=>'Ngarkimi u anulua.','Upload complete — translation requested.'=>'Ngarkimi u përfundua — përkthimi u kërkua.','Upload expired before it finished'=>'Ngarkimi skadoi para se të përfundonte','Upload in progress — continue or cancel'=>'Ngarkim në vazhdim — vazhdo ose anulo','Upload this component?'=>'Ta ngarkoj këtë komponent?','Upload was not accepted'=>'Ngarkimi nuk u pranua','Uploading'=>'Po ngarkohet','Uploading part %1$d of %2$d…'=>'Po ngarkohet pjesa %1$d nga %2$d…','Uploading…'=>'Po ngarkohet…','Verified'=>'E verifikuar','Verify response was missing site_token.'=>'Përgjigjes së verifikimit i mungonte site_token.','Version %s'=>'Versioni %s','What is sent when Babilim checks this site'=>'Çfarë dërgohet kur Babilim kontrollon këtë sajt','What is sent when you enable Babilim'=>'Çfarë dërgohet kur aktivizoni Babilim','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Kur diçka dështon brenda Babilim, dërgo një raport gabimi te shërbimi Babilim që të mund të publikohet si çështje publike në GitHub. Raporti dërgohet sikur vjen nga ky sajt, me të njëjtin autentikim si çdo kërkesë tjetër te shërbimi Babilim. Shërbimi publikon vetëm kodin e gabimit dhe versionet si çështje publike në GitHub; çështja publike nuk përmban adresën e sajtit, përmbajtje apo shtigje skedarësh. E çaktivizuar si parazgjedhje.','Where you saw this (optional)'=>'Ku e keni parë këtë (opsionale)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Kur kjo është aktive, përkthimet që shërbimi i liston si të disponueshme për gjuhët që administroni instalohen gjatë sinkronizimit dy herë në ditë.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'I gabuar për këtë kontekst','Wrong meaning'=>'Kuptim i gabuar','Wrong plural form'=>'Trajtë e gabuar shumësi','Wrong term'=>'Term i gabuar','Yes'=>'Po','You are not allowed to do this.'=>'Nuk keni leje ta bëni këtë.','Your PHP version, for compatibility.'=>'Versioni juaj i PHP, për përputhshmëri.','Your WordPress version, to serve compatible translation files.'=>'Versioni juaj i WordPress, për të shërbyer skedarë përkthimi të përputhshëm.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Kodi juaj i ri i rikthimit: %s. Ruajeni diku të sigurt — kodi i mëparshëm nuk funksionon më.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Raporti juaj përpunohet automatikisht nga modele AI dhe mund ta përmirësojë këtë përkthim për sajte të tjerë.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Sajti juaj u përgjigj, por jo me atë që priteshim. REST API mund të jetë rishkruar nga një shtojcë tjetër, ose ai endpoint mund të jetë ruajtur në cache; ju lutemi përjashtojeni /wp-json/babilim/v1/challenge nga cache-imi dhe rishkrimi.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Sajti juaj u përgjigj shumë ngadalë. Provoni përsëri më vonë dhe kontrolloni që strehuesi juaj të mos jetë shumë i ngadaltë ose i mbingarkuar.','Zip has no manifest.json.'=>'Zip-i nuk ka manifest.json.','Zip is missing expected default file: %s'=>'Arkivit zip i mungon kartela e pritshme e parazgjedhur: %s','Zip is missing expected file: %s'=>'Zip-it i mungon kartela e pritur: %s','_manifest.json has an unexpected structure'=>'_manifest.json ka një strukturë të papritur','could not read _manifest.json: %s'=>'nuk u lexua dot _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest mungon ose ka \'%s\' të pavlefshëm.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' i expected_manifest nuk është ID ndërtimi e vlefshme.','failed to parse _manifest.json: %s'=>'analizimi i _manifest.json dështoi: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'do të linte jetim %1$d nga %2$d komponentë të menaxhuar (më shumë se gjysma)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'do të linte jetim çdo komponent të menaxhuar %1$s (%2$d nga %2$d)','l10n.php entry count mismatch for %s'=>'Mospërputhje e numrit të hyrjeve l10n.php për %s','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json ka \'default_domain_entries\' të pavlefshëm.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json ka \'default_domain_files\' të pavlefshëm.','manifest.json in the zip is not valid JSON.'=>'manifest.json në zip nuk është JSON i vlefshëm.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json mungon ose ka \'%s\' të pavlefshëm.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json mungon ose ka \'build_no\' të pavlefshëm.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json mungon ose ka \'entries\' të pavlefshëm.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json mungon ose ka \'extra_domains\' të pavlefshëm.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json mungon ose ka \'files\' të pavlefshëm.','manifest.json\'s \'%s\' does not match the expected value.'=>'\'%s\' i manifest.json nuk përputhet me vlerën e pritur.','manifest.json\'s \'contract\' is not a valid version string.'=>'\'contract\' i manifest.json nuk është varg versioni i vlefshëm.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'\'kind\' i manifest.json duhet të jetë \'plugin\' ose \'theme\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' i manifest.json nuk është ID ndërtimi e vlefshme.','manifest.json\'s \'status\' must be \'published\'.'=>'Gjendje: \'status\' në manifest.json duhet të jetë \'published\'.','nonce must be a hexadecimal string.'=>'nonce duhet të jetë varg heksadecimal.','per day'=>'në ditë','rc_…'=>'rc_…','sha256 mismatch for %s'=>'Mospërputhje sha256 për %s','sha256 mismatch for default/%s'=>'Mospërputhje sha256 për default/%s','component kind in the sweep brake messageplugin'=>'shtojcë','component kind in the sweep brake messagetheme'=>'temë','problem report categoryOther'=>'Tjetër','translation statusAvailable'=>'I disponueshëm','translation statusInstalled'=>'I instaluar']];